from pathlib import Path
import json,base64
O=Path(__file__).resolve().parent
D=json.loads((O/'samples.json').read_text());D['images']={p.name:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in sorted((O/'originals').glob('*.png'))}
html=r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Puente · acabados</title><style>
*{box-sizing:border-box}body{margin:0;background:#101820;color:#edf2f8;font:16px/1.5 system-ui}header,main{max-width:1500px;margin:auto;padding:24px}h1{font-size:42px;margin:8px 0}p{max-width:1000px;color:#b8c6d7}button,select{font:inherit;background:#243549;color:#edf2f8;border:1px solid #60758e;border-radius:8px;padding:10px;min-height:44px;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #ffd59a}button[aria-pressed=true]{background:#b9d9ff;color:#132135}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{min-width:0;border:1px solid #46576c;border-radius:12px;overflow:hidden;background:#192530}.info{padding:14px}.info h2{margin:0;font-size:22px}.info p{font-size:14px;min-height:42px}.shot{width:100%;display:block;cursor:zoom-in;background:#131d28;object-fit:contain;max-height:510px}aside{padding:18px;background:#233447;border-radius:12px;margin:18px 0}.note{font-size:14px}dialog{width:min(1500px,97vw);max-height:95vh;background:#111b25;color:#edf2f8;border:1px solid #7890aa;border-radius:12px}dialog::backdrop{background:#000d}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pair img,.single img{width:100%;display:block}.modaltools{position:sticky;top:0;background:#111b25;padding:8px}#summary{font-size:20px;font-weight:700}a{color:#bddcff}@media(max-width:650px){header,main{padding:16px}h1{font-size:32px}.grid{grid-template-columns:1fr}.pair{gap:4px}}
</style><header><small>SPOTLIGHT NEXT · LABORATORIO COMPOSE</small><h1>Puente, sin medias tintas.</h1><p>Ocho acabados completos y deliberadamente distintos. Colores dominantes, letras, escalas, rellenos, selección, densidad y material cambian juntos. La composición sigue siendo Puente.</p><aside>Esta vez cada X es <b>una combinación real ya renderizada</b>. Elegí por su apariencia completa. En la sección Transparencia se aísla sólo la opacidad, sobre el mismo fondo con texto.</aside></header><main>
<div class="tools"><label>Explorar <select id="group"><option value="look">Acabados completos · 8</option><option value="opacity">Transparencia · 4</option></select></label><label>Dispositivo <select id="device"><option value="tablet">Tablet · 1200 × 800 dp</option><option value="phone">Teléfono · 412 × 860 dp</option></select></label><label>Escena <select id="scene"><option value="acciones">Aplicación y acciones</option><option value="contexto">Documento y contexto</option></select></label></div><p id="conditions" class="note"></p><div class="tools"><label>A <select id="left"></select></label><label>B <select id="right"></select></label><button id="compare">Comparar lado a lado</button><button id="reference">Ver Puente anterior</button></div><section id="grid" class="grid"></section>
<aside><h2>Mi elección de laboratorio</h2><div id="summary"></div><p>Una X elige un acabado completo. La O registra una preferencia de opacidad separada: no se aplica automáticamente a esa X. No se integra nada en la app.</p><button id="export">Guardar elección JSON</button></aside><h2>Cuáles miraría primero</h2><p><b>X02 Papel editorial</b> si querés una personalidad cálida y muy distinta. <b>X03 Cobalto eléctrico</b> si buscás identidad inmediata. <b>X08 Blanco brutal</b> si preferís jerarquía gráfica y contundencia. X01 Terminal y X05 Señal son los extremos más técnicos o intensos.</p><h2>Transparencia: efecto y coste</h2><p>100 %, 90 %, 76 % y 60 % son valores de opacidad de superficie. Menor opacidad significa más transparencia. Se renderizan de verdad en Compose sobre un fondo con texto, sin blur ni filtro de la galería. El 60 % es un extremo para comparar, no una recomendación: el fondo compite con la lectura. Los encabezados tienen una segunda capa con la misma opacidad, por lo que su opacidad efectiva es mayor.</p><h2>Qué estás viendo</h2><p>40 capturas Compose nuevas y 2 referencias anteriores exactas. Mismos cuatro resultados, consulta, selección y documento ficticio. Los acabados no son equivalentes al tema claro/oscuro de producción: cada uno tiene su paleta propuesta. No hay cambio de tema artificial sobre una captura.</p><p>Robolectric API 33, tablet 1200 × 800 dp y teléfono 412 × 860 dp. Dos superficies representadas dentro de un único lienzo. Inter, Geist y fuentes de sistema ya disponibles. El tamaño del contexto móvil se adapta al espacio restante y permite scroll. Sin ejecución externa, APK ni cambios en Focus Studio.</p><p>Faltan pruebas físicas de overlay, IME, texto ampliado, fluidez y lectura sobre aplicaciones reales. La transparencia no queda certificada por las comprobaciones de contraste opaco.</p></main><dialog id="modal"><div class="modaltools"><button id="close">Cerrar · Escape</button><p id="caption"></p></div><div id="modalbody"></div></dialog><script>
const D=__DATA__, $=s=>document.querySelector(s), chosen={look:'X02',opacity:'O01'};
function current(){return D.items.filter(i=>i.group===$('#group').value)}
function src(id){return D.images[$('#device').value+'-'+id+'-dark-'+$('#scene').value+'.png']}
function zoom(ids,ref=false){$('#caption').textContent=ref?'Puente anterior exacto · acciones':ids.join(' frente a ')+' · '+$('#device').selectedOptions[0].text+' · '+$('#scene').value;$('#modalbody').className=ids.length>1?'pair':'single';$('#modalbody').innerHTML=ids.map(id=>'<img alt="Captura Compose '+id+'" src="'+(ref?D.images[$('#device').value+'-R00-dark-acciones.png']:src(id))+'">').join('');$('#modal').showModal()}
function summary(){$('#summary').textContent='Acabado: '+chosen.look+' · opacidad para estudiar: '+chosen.opacity}
function render(){const look=$('#group').value==='look';$('#scene').disabled=!look;if(!look)$('#scene').value='acciones';$('#conditions').textContent=look?'Cambian los acabados completos. Misma búsqueda, datos y dimensiones. Cada tarjeta explica su ventaja y su inconveniente.':'Comparación controlada: misma variante Hielo, misma letra, rellenos y fondo. Sólo cambia la opacidad.';const list=current();for(const s of ['#left','#right'])$(s).innerHTML=list.map(i=>'<option value="'+i.id+'">'+i.id+' · '+i.name+'</option>').join('');$('#right').selectedIndex=1;$('#grid').innerHTML=list.map(i=>'<article class="card"><div class="info"><h2>'+i.id+' · '+i.name+'</h2><p>'+i.note+'</p><p class="note">'+Object.entries(i.tokens).map(([k,v])=>({'padding_dp':'Relleno dp','row_dp':'Fila dp','query_dp':'Barra dp','gap_dp':'Separación dp','radius_dp':'Radio dp','opacity_percent':'Opacidad %','type_scale':'Escala letra'}[k])+': '+v).join(' · ')+'</p><button data-pick="'+i.id+'" aria-pressed="'+(chosen[i.group]===i.id)+'">Me interesa '+i.id+'</button></div><img class="shot" alt="Captura Compose '+i.id+'" data-zoom="'+i.id+'" src="'+src(i.id)+'"></article>').join('');document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>zoom([b.dataset.zoom]));document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{chosen[$('#group').value]=b.dataset.pick;summary();render()})}
for(const s of ['#group','#device','#scene'])$(s).onchange=render;$('#compare').onclick=()=>zoom([$('#left').value,$('#right').value]);$('#reference').onclick=()=>zoom(['R00'],true);$('#close').onclick=()=>$('#modal').close();$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({kind:'lab-complete-look-plus-separate-opacity-preference',chosen},null,2)],{type:'application/json'}));a.download='Mi-Puente-Extremos.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};summary();render();
</script></html>'''
(O/'Galeria-Puente-Extremos.html').write_text(html.replace('__DATA__',json.dumps(D,ensure_ascii=False,sort_keys=True)))
